import base64
import inspect
from collections import Mapping, OrderedDict


def arg_names(func):
    return inspect.getargspec(func).args


def encode(text):
    return base64.encodestring(text.encode()).decode()


def decode(data):
    return base64.decodestring(data.encode()).decode()


def merge(a, b):
    if not isinstance(a, Mapping) or not isinstance(b, Mapping):
        raise TypeError("expected mappings")
    merged = OrderedDict(a)
    merged.update(b)
    return merged

