import pytest

from compat.util import arg_names, decode, encode, merge


def test_arg_names():
    assert arg_names(lambda a, b: None) == ["a", "b"]


def test_base64_round_trip():
    assert encode("hi") == "aGk=\n"
    assert decode("aGk=\n") == "hi"


def test_merge_keeps_order_and_overrides():
    assert list(merge({"a": 1, "b": 2}, {"b": 3, "c": 4}).items()) == [("a", 1), ("b", 3), ("c", 4)]


def test_merge_rejects_non_mappings():
    with pytest.raises(TypeError):
        merge([1], {"a": 1})
